    metadata = {k: v for k, v in raw.items() if k not in known}
    return Event(
        event_id=str(raw["event_id"]),
        customer_id=str(raw["customer_id"]),
        ts=ts,
        kind=kind,
        seq=seq,
        page=page,
        amount_cents=amount if kind != "activity" else 0,
        ref=ref,
        metadata=dict(metadata),
    )

